 "content": "from collections import Counter


def transform(grid):
    """Copy the embedded straight motif, centered on each marker."""
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    bg = Counter(v for row in g for v in row).most_common(1)[0][0]
    counts = Counter(v for row in g for v in row if v != bg)
    marker = counts.most_common(1)[0][0]

    # The source motif is the longest straight contiguous run that is neither
    # background nor marker; its orientation is preserved when copied.
    best = None
    for r in range(h):
        c = 0
        while c < w:
            if g[r][c] == bg or g[r][c] == marker:
                c += 1
                continue
            start = c
            while c < w and g[r][c] != bg and g[r][c] != marker:
                c += 1
            if best is None or c - start > len(best[2]):
                best = ("h", r, g[r][start:c])
    for c in range(w):
        r = 0
        while r < h:
            if g[r][c] == bg or g[r][c] == marker:
                r += 1
                continue
            start = r
            while r < h and g[r][c] != bg and g[r][c] != marker:
                r += 1
            if best is None or r - start > len(best[2]):
                best = ("v", c, [g[y][c] for y in range(start, r)])
    if best is None:
        return g

    orient, fixed, motif = best
    offset = (len(motif) - 1) // 2
    clues = [(r, c) for r in range(h) for c in range(w) if g[r][c] == marker]
    for r, c in clues:
        if orient == "h":
            start = c - offset
            for j, value in enumerate(motif):
                x = start + j
                if 0 <= x < w:
                    g[r][x] = value
        else:
            start = r - offset
            for j, value in enumerate(motif):
                y = start + j
                if 0 <= y < h:
                    g[y][c] = value
    return g


